import React, { useState, useRef } from 'react';
import { 
  Container, Row, Col, Card, 
  Form, Button, Alert, Table, 
  Badge, ProgressBar, Spinner 
} from 'react-bootstrap';
import { useNotification } from '../contexts/NotificationContext';

const SBUBatchSearchPage = () => {
  const { showNotification, showError, showSuccess } = useNotification();
  const fileInputRef = useRef(null);
  
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [keywords, setKeywords] = useState('');
  const [results, setResults] = useState([]);
  const [stats, setStats] = useState({
    total: 0,
    found: 0,
    notFound: 0,
    active: 0,
    expired: 0
  });

  const parseKeywords = (input) => {
    return input
      .split('\n')
      .map(line => line.trim())
      .filter(line => line.length > 0);
  };

  const searchSBU = async (keyword) => {
    try {
      const response = await fetch(
        `http://localhost:5000/api/lpjk/sbu/search?keyword=${encodeURIComponent(keyword)}&type=nama`
      );
      return await response.json();
    } catch (error) {
      throw error;
    }
  };

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target.result;
      setKeywords(content);
    };
    reader.readAsText(file);
  };

  const handleBatchSearch = async () => {
    const keywordList = parseKeywords(keywords);
    
    if (keywordList.length === 0) {
      showError('Masukkan keyword atau upload file CSV');
      return;
    }

    if (keywordList.length > 50) {
      showError('Maksimal 50 keyword per batch');
      return;
    }

    setLoading(true);
    setProgress(0);
    setResults([]);

    const allResults = [];
    let foundCount = 0;
    let activeCount = 0;
    let expiredCount = 0;

    try {
      for (let i = 0; i < keywordList.length; i++) {
        const keyword = keywordList[i];
        
        try {
          const result = await searchSBU(keyword);
          
          if (result.status === 'success' && result.data.length > 0) {
            foundCount++;
            
            result.data.forEach(item => {
              if (item.status === 'AKTIF') activeCount++;
              if (item.status === 'EXPIRED') expiredCount++;
              
              allResults.push({
                keyword,
                ...item,
                batchId: i
              });
            });
          }
        } catch (error) {
          console.error(`Error searching ${keyword}:`, error);
        }

        // Update progress
        const newProgress = Math.round(((i + 1) / keywordList.length) * 100);
        setProgress(newProgress);
      }

      setResults(allResults);
      setStats({
        total: keywordList.length,
        found: foundCount,
        notFound: keywordList.length - foundCount,
        active: activeCount,
        expired: expiredCount
      });

      showSuccess(`Batch search selesai: ${foundCount} ditemukan dari ${keywordList.length} keyword`);
    } catch (error) {
      console.error('Batch search error:', error);
      showError('Gagal melakukan batch search');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = () => {
    if (results.length === 0) {
      showError('Tidak ada data untuk diexport');
      return;
    }

    const headers = ['Keyword', 'Nama Perusahaan', 'NPWP', 'Kualifikasi', 'Klasifikasi', 'Status', 'Grade', 'Masa Berlaku'];
    const rows = results.map(item => [
      item.keyword,
      item.nama_perusahaan,
      item.npwp,
      item.kualifikasi,
      item.klasifikasi,
      item.status,
      item.grade,
      item.masa_berlaku
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(cell => 
        typeof cell === 'string' && cell.includes(',') ? `"${cell}"` : cell
      ).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sbu-batch-results-${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);

    showSuccess('Data berhasil diexport');
  };

  const handleClear = () => {
    setKeywords('');
    setResults([]);
    setProgress(0);
    setStats({
      total: 0,
      found: 0,
      notFound: 0,
      active: 0,
      expired: 0
    });
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const sampleKeywords = `PT Adhi Karya
PT Waskita Karya
PT Wijaya Karya
PT PP (Persero)
PT Hutama Karya`;

  const loadSample = () => {
    setKeywords(sampleKeywords);
    showNotification('Sample keywords loaded', 'info');
  };

  return (
    <Container className="py-4">
      <Row className="mb-4">
        <Col>
          <h1 className="display-6 fw-bold">
            <i className="fas fa-search-plus me-2"></i>
            SBU Batch Search
          </h1>
          <p className="text-muted">
            Cari multiple SBU sekaligus dari file CSV atau daftar keyword
          </p>
        </Col>
      </Row>

      {/* Input Section */}
      <Row className="mb-4">
        <Col lg={8}>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <h6 className="mb-0">
                <i className="fas fa-keyboard me-2"></i>
                Input Keywords
              </h6>
            </Card.Header>
            <Card.Body>
              <Form.Group className="mb-3">
                <Form.Label>
                  <i className="fas fa-list me-1"></i>
                  Daftar Keyword (satu per baris)
                </Form.Label>
                <Form.Control
                  as="textarea"
                  rows={8}
                  placeholder="Masukkan nama perusahaan, satu per baris"
                  value={keywords}
                  onChange={(e) => setKeywords(e.target.value)}
                  disabled={loading}
                />
              </Form.Group>

              <div className="d-flex flex-wrap gap-2">
                <input
                  type="file"
                  accept=".csv,.txt"
                  onChange={handleFileUpload}
                  ref={fileInputRef}
                  style={{ display: 'none' }}
                  id="file-upload"
                />
                <label htmlFor="file-upload">
                  <Button as="span" variant="outline-primary" className="me-2">
                    <i className="fas fa-upload me-1"></i>
                    Upload CSV/TXT
                  </Button>
                </label>
                
                <Button
                  variant="outline-secondary"
                  onClick={loadSample}
                  disabled={loading}
                >
                  <i className="fas fa-magic me-1"></i>
                  Load Sample
                </Button>
                
                <Button
                  variant="outline-danger"
                  onClick={handleClear}
                  disabled={loading}
                >
                  <i className="fas fa-trash me-1"></i>
                  Clear
                </Button>
              </div>
            </Card.Body>
          </Card>
        </Col>
        
        <Col lg={4}>
          <Card className="shadow-sm h-100">
            <Card.Header className="bg-light">
              <h6 className="mb-0">
                <i className="fas fa-info-circle me-2"></i>
                Informasi Batch Search
              </h6>
            </Card.Header>
            <Card.Body className="d-flex flex-column">
              <div className="mb-3">
                <h6>Format File:</h6>
                <p className="small text-muted mb-2">
                  • CSV/TXT dengan satu keyword per baris
                </p>
                <p className="small text-muted mb-2">
                  • Maksimal 50 keyword per batch
                </p>
                <p className="small text-muted">
                  • Setiap keyword akan dicari di LPJK
                </p>
              </div>
              
              <div className="mt-auto">
                <Button
                  variant="primary"
                  className="w-100"
                  onClick={handleBatchSearch}
                  disabled={loading || !keywords.trim()}
                >
                  {loading ? (
                    <>
                      <Spinner
                        as="span"
                        animation="border"
                        size="sm"
                        className="me-2"
                      />
                      Searching... ({progress}%)
                    </>
                  ) : (
                    <>
                      <i className="fas fa-search me-1"></i>
                      Start Batch Search
                    </>
                  )}
                </Button>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Progress Bar */}
      {loading && (
        <Row className="mb-4">
          <Col>
            <Card className="shadow-sm">
              <Card.Body>
                <div className="d-flex justify-content-between mb-2">
                  <span>Progress</span>
                  <span>{progress}%</span>
                </div>
                <ProgressBar now={progress} animated />
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}

      {/* Stats */}
      {stats.total > 0 && (
        <Row className="mb-4">
          <Col>
            <Card className="shadow-sm">
              <Card.Header className="bg-light">
                <h6 className="mb-0">
                  <i className="fas fa-chart-bar me-2"></i>
                  Hasil Batch Search
                </h6>
              </Card.Header>
              <Card.Body>
                <Row>
                  <Col md={2} className="text-center">
                    <div className="display-6 fw-bold text-primary">{stats.total}</div>
                    <small className="text-muted">Total Keyword</small>
                  </Col>
                  <Col md={2} className="text-center">
                    <div className="display-6 fw-bold text-success">{stats.found}</div>
                    <small className="text-muted">Ditemukan</small>
                  </Col>
                  <Col md={2} className="text-center">
                    <div className="display-6 fw-bold text-danger">{stats.notFound}</div>
                    <small className="text-muted">Tidak Ditemukan</small>
                  </Col>
                  <Col md={3} className="text-center">
                    <div className="display-6 fw-bold text-info">{stats.active}</div>
                    <small className="text-muted">Status Aktif</small>
                  </Col>
                  <Col md={3} className="text-center">
                    <div className="display-6 fw-bold text-warning">{stats.expired}</div>
                    <small className="text-muted">Status Expired</small>
                  </Col>
                </Row>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}

      {/* Results */}
      {results.length > 0 && (
        <Row className="mb-4">
          <Col>
            <Card className="shadow-sm">
              <Card.Header className="bg-light d-flex justify-content-between align-items-center">
                <div>
                  <i className="fas fa-list me-2"></i>
                  Hasil ({results.length} data)
                </div>
                <div>
                  <Button
                    variant="success"
                    size="sm"
                    onClick={handleExport}
                  >
                    <i className="fas fa-download me-1"></i>
                    Export All
                  </Button>
                </div>
              </Card.Header>
              <Card.Body className="p-0">
                <div style={{ maxHeight: '500px', overflowY: 'auto' }}>
                  <Table hover responsive className="mb-0">
                    <thead className="table-light sticky-top">
                      <tr>
                        <th>Keyword</th>
                        <th>Nama Perusahaan</th>
                        <th>NPWP</th>
                        <th>Kualifikasi</th>
                        <th>Klasifikasi</th>
                        <th>Status</th>
                        <th>Grade</th>
                        <th>Detail</th>
                      </tr>
                    </thead>
                    <tbody>
                      {results.map((item, index) => (
                        <tr key={index}>
                          <td>
                            <Badge bg="secondary">{item.keyword}</Badge>
                          </td>
                          <td>
                            <strong>{item.nama_perusahaan}</strong>
                            <div className="small text-muted">
                              {item.kota}, {item.provinsi}
                            </div>
                          </td>
                          <td>
                            <code>{item.npwp}</code>
                          </td>
                          <td>{item.kualifikasi}</td>
                          <td>
                            <Badge bg={
                              item.klasifikasi === 'BESAR' ? 'primary' :
                              item.klasifikasi === 'MENENGAH' ? 'info' : 'secondary'
                            }>
                              {item.klasifikasi}
                            </Badge>
                          </td>
                          <td>
                            <Badge bg={item.status === 'AKTIF' ? 'success' : 'danger'}>
                              {item.status}
                            </Badge>
                          </td>
                          <td>
                            <Badge bg="warning">Grade {item.grade}</Badge>
                          </td>
                          <td>
                            <Button
                              variant="outline-primary"
                              size="sm"
                              onClick={() => window.open(item.url_detail, '_blank')}
                            >
                              <i className="fas fa-external-link-alt"></i>
                            </Button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </Table>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}

      {/* Tips */}
      <Row>
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <i className="fas fa-lightbulb me-2"></i>
              Tips Batch Search
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-file-csv text-primary"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>File CSV</h6>
                      <p className="small text-muted mb-0">
                        Upload file CSV dengan kolom 'nama_perusahaan'
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-chart-line text-success"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Analisis Vendor</h6>
                      <p className="small text-muted mb-0">
                        Gunakan untuk analisis multiple vendor sekaligus
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-filter text-warning"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Filter Hasil</h6>
                      <p className="small text-muted mb-0">
                        Export dan filter di Excel untuk analisis lanjutan
                      </p>
                    </div>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default SBUBatchSearchPage;